window.AUTH=window.AUTH||{};window.AUTH["16-1363"]={"d":"16-1363","id":"2018/16-1363","n":"Nielsen v. Preap","briefs":[{"k":"petitioner","label":"Brief of petitioners Kirstjen M. Nielsen, Secretary of Homeland Security, et al.","date":"2018-06-01","url":"https://www.supremecourt.gov/DocketPDF/16/16-1363/49018/20180601171509498_16-1363tsNielsen.pdf","side":"pet","n":61},{"k":"respondent","label":"Brief of respondents Mony Preap, et al.","date":"2018-08-06","url":"https://www.supremecourt.gov/DocketPDF/16/16-1363/58566/20180806152456058_No%2016%201363%20Kirsten%20M%20Nielsen%20v%20Mony%20Preap%20et%20al%20Brief%20for%20Respondents.pdf","side":"res","n":66},{"k":"reply","label":"Reply of petitioners Kirstjen M. Nielsen, Secretary of Homeland Security, et al.","date":"2018-09-05","url":"https://www.supremecourt.gov/DocketPDF/16/16-1363/62824/20180905175727148_16-1363rbUnitedStates.pdf","side":"pet","n":28}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/16-1363_a86c.pdf","tr":true,"items":[{"t":"case","label":"Adams v. Holder","cite":"692 F.3d 91","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/692/91/","by":{"0":"25"}},{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"entrusted to the discretion of the Federal Government.","cite":"567 U.S. 387, 409"}]},{"t":"case","label":"Barnhart v. Peabody Coal Co.","cite":"537 U.S. 149","y":2003,"id":"2002/01-705","sc":1,"by":{"0":"11, 28, 29","1":"50","2":"8, 10"},"q":[{"src":"brief","b":0,"text":"a provision that a detention hearing ‘shall be held immediately upon the [detainee’s] first appearance before the judicial officer’ did not bar detention after a tardy hearing.","cite":"537 U.S. at 159"},{"src":"brief","b":1,"text":"‘specify a consequence for noncompliance with [a] statutory timing provision[],’","cite":"537 U.S. 149, 159"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"a provision that a detention hearing ‘shall be held immediately upon the [detainee’s] first appearance before the judicial officer’ did not bar detention after a tardy hearing.","cite":"537 U. S., at 159"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"‘if a statute does not specify a consequence for noncompliance with statutory timing provisions, the federal courts will not in the ordinary course impose their own coercive sanction.’","cite":"537 U. S., at 159"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"presumably aware that we do not readily infer congressional intent to limit an agency’s power to get a mandatory job done merely from a specification to act by a certain time.","cite":"537 U. S., at 160"}]},{"t":"case","label":"Brock v. Pierce Cnty.","cite":"476 U.S. 253","y":1986,"id":"1985/85-385","sc":1,"by":{"0":"28","1":"49","2":"8"}},{"t":"case","label":"Bullard v. Blue Hills Bank","cite":"135 S. Ct. 1686","y":2015,"id":"2014/14-116","sc":1,"by":{"0":"21"}},{"t":"case","label":"Castañeda v. Souza","cite":"810 F.3d 15","y":2015,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/810/15/","by":{"0":"6, 19, 21","1":"passim","2":"6"},"q":[{"src":"brief","b":1,"text":"Congress chose a word, ‘when,’ that naturally conveys some degree of immediacy, as opposed to a purely conditional word, such as ‘if.’","cite":"810 F.3d 15, 38"}]},{"t":"case","label":"Chevron U.S.A. Inc. v. Natural Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"by":{"0":"12, 39","1":"passim"},"q":[{"src":"brief","b":1,"text":"must give effect to the unambiguously expressed intent of Congress.","cite":"467 U.S. 837, 842-43"}]},{"t":"case","label":"Demore v. Kim","cite":"538 U.S. 510","y":2003,"id":"2002/01-1491","sc":1,"by":{"0":"passim","1":"passim","2":"9, 12, 16, 18, 19"},"q":[{"src":"brief","b":0,"text":"justifiably concerned that deportable criminal aliens who are not detained continue to engage in crime and 1 Congress has transferred from the Attorney General to the Secretary of Homeland Security the enforcement of the Immigration and Nationality Act, 8 U.S.C. 1101 et seq., but the Attorney General retains authority over the administration of removal proceedings under 8 U.S.C. 1229a and questions of law. See, e.g., 6 U.S.C. 202(3), 251, 271(b), 542 note, 557; 8 U.S.C. 1103(a)(1) and (g), 1551 note. fail to appear for their removal hearings in large numbers.","cite":"538 U.S. 510, 513"},{"src":"brief","b":0,"text":"after criminal aliens were identified as deportable, 77% were arrested at least once more and 45%—nearly half—were arrested multiple times before their deportation proceedings even began.","cite":"538 U.S. at 518"},{"src":"brief","b":1,"text":"to identify and track deportable criminal aliens while they are still in the criminal justice system, and to complete removal proceedings against them as promptly as possible","cite":"538 U.S. at 530 n.13"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"continue to engage in crime [or] fail to appear for their removal hearings.","cite":"538 U. S., at 513"},{"src":"opinion","who":"Justice Thomas, concurring in part and concurring in the judgment","text":"unequivocally deprives federal courts of jurisdiction to set aside ‘any action or decision’ by the [Secretary]","cite":"538 U. S. 510, 533"},{"src":"argument","who":"Mr. Tripp","text":"I mean, Demore versus Kim squarely upheld this statute. They are not asking the Court to overrule Demore. They're not saying that it's wrongly decided."},{"src":"argument","who":"Mr. Tripp","text":"I -- I think the answer is no under the analysis in Demore. So, first of all, when a -- when a criminal alien is finally put into removal proceedings, they know this is happening, they've been arrested, all of that."},{"src":"argument","who":"Ms. Wang","text":"And the second response is that the Court decided in Demore in 2003 that applying the mandatory detention rule, at least, not considering the question before the Court now, is constitutional."}]},{"t":"case","label":"Forest Grove Sch. Dist. v. T. A.","cite":"557 U.S. 230","y":2009,"id":"2008/08-305","sc":1,"by":{"0":"33"}},{"t":"case","label":"Hosh v. Lucero","cite":"680 F.3d 375","y":2012,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/680/375/","by":{"0":"6, 7, 17, 29, 40","2":"21"}},{"t":"case","label":"INS v. Aguirre-Aguirre","cite":"526 U.S. 415","y":1999,"id":"1998/97-1754","sc":1,"by":{"0":"39","1":"45","2":"20"},"q":[{"src":"brief","b":0,"text":"determination and ruling by the Attorney General with respect to all questions of law shall be controlling.","cite":"526 U.S. at 424"},{"src":"brief","b":0,"text":"the BIA should be accorded Chevron deference.","cite":"526 U.S. at 425"},{"src":"brief","b":2,"text":"clear that principles of Chevron deference are applicable to this statutory scheme.","cite":"526 U.S. 415, 424"}]},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"by":{"0":"2, 4, 13, 15","1":"16, 19, 38","2":"2, 5, 15, 17"},"q":[{"src":"brief","b":0,"text":"Section 1226(c), however, carves out a statutory category of aliens who may not be released under § 1226(a).","cite":"138 S. Ct. at 837"},{"src":"brief","b":0,"text":"expressly and unequivocally imposes an affirmative prohibition on releasing detained aliens under any other conditions.","cite":"138 S. Ct. at 847"},{"src":"brief","b":1,"text":"Section 1226(c) . . . carves out a statutory category of aliens who may not be released under § 1226(a).","cite":"138 S. Ct. 830, 837"},{"src":"brief","b":2,"text":"expressly and unequivocally imposes an affirmative prohibition on","cite":"138 S. Ct. 830, 847"},{"src":"brief","b":2,"text":"[s]potting a constitutional issue does not give a court the authority to rewrite a statute as it pleases.","cite":"138 S. Ct. at 843"},{"src":"argument","who":"Justice Breyer","text":"As you know from my opinion in Jennings, I think that's unconstitutional. But the Court didn't decide the contrary, all right? So assume, as I am assuming, that this paragraph is ambiguous at most in your favor."}]},{"t":"case","label":"Lora v. Shanahan","cite":"804 F.3d 601","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/804/601/","by":{"0":"6, 25, 29, 40","2":"13, 20"},"q":[{"src":"brief","b":0,"text":"[T]he BIA’s interpretation has the added benefit of accounting for practical concerns arising in connection with enforcing the statute.","cite":"804 F.3d 601, 612"},{"src":"brief","b":2,"text":"the resources to appear at every location where a qualifying alien is being released,","cite":"804 F.3d 601, 612-613"},{"src":"brief","b":2,"text":"premise[d] the success of its mandatory detention scheme on the capacity of DHS to appear at the jailhouse door to take custody of an alien at the precise moment of release.","cite":"804 F.3d at 612"}]},{"t":"case","label":"Negusie v. Holder","cite":"555 U.S. 511","y":2009,"id":"2008/07-499","sc":1,"by":{"0":"39","2":"21"}},{"t":"case","label":"Olmos v. Holder","cite":"780 F.3d 1313","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/780/1313/","by":{"0":"6, 29, 40"}},{"t":"case","label":"Regions Hosp. v. Shalala","cite":"522 U.S. 448","y":1998,"id":"1997/96-1375","sc":1,"by":{"0":"28","1":"49","2":"8"}},{"t":"case","label":"Reid v. Donelan","cite":"819 F.3d 486","y":2016,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/819/486/","by":{"0":"23"}},{"t":"case","label":"Scialabba v. Cuellar de Osorio","cite":"134 S. Ct. 2191","y":2014,"id":"2013/12-930","sc":1,"by":{"0":"39"},"q":[{"src":"brief","b":0,"text":"Principles of Chevron deference apply when the BIA interprets the immigration laws.","cite":"134 S. Ct. 2191, 2203"}]},{"t":"case","label":"Sylvain v. Attorney Gen. of U.S.","cite":"714 F.3d 150","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/714/150/","by":{"0":"6, 7, 12, 23, 29, 40","1":"18","2":"9"},"q":[{"src":"brief","b":0,"text":"reintroduce[] discretion into the process and bestow[] a windfall upon dangerous criminals.","cite":"714 F.3d 150, 160-161"}]},{"t":"case","label":"Texas Dep’t of Hous. & Cmty. Affairs v. Inclusive Communities Project, Inc.","cite":"135 S. Ct. 2507","y":2015,"id":"2014/13-1371","sc":1,"by":{"0":"33"}},{"t":"case","label":"Torres v. Lynch","cite":"136 S. Ct. 1619","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1619/","sc":1,"by":{"0":"14"},"q":[{"src":"brief","b":0,"text":"convey an idea or impression of.","cite":"136 S. Ct. 1619, 1625 nn.3-4"}]},{"t":"case","label":"United States v. Montalvo‐Murillo","cite":"495 U.S. 711","y":1990,"id":"1989/89-163","sc":1,"by":{"0":"11, 28, 30","1":"49","2":"1, 8, 9, 13"},"q":[{"src":"brief","b":0,"text":"visit upon the Government and the citizens a severe penalty by mandating release of possibly dangerous defendants.","cite":"495 U.S. at 720"},{"src":"brief","b":2,"text":"some errors in the application of the time requirements [still] occur.","cite":"495 U.S. at 720"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"visit upon the Government and the citizens a severe penalty by mandating release of possibly dangerous defendants every time some deviation from the [statutory] strictures . . . occur[red].","cite":"495 U. S., at 720"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"the design and function of the statute.","cite":"495 U. S., at 719"},{"src":"argument","who":"Mr. Tripp","text":"I think this is -- the Montalvo-Murillo, these better late than never cases, I think, are squarely on point for our understanding of (c)(1)."}]},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"by":{"0":"31","1":"38, 39, 45"},"q":[{"src":"brief","b":1,"text":"Freedom from imprisonment—from government custody, detention, or other forms of physical restraint—lies at the heart of the liberty","cite":"533 U.S. 678, 690"},{"src":"argument","who":"Justice Breyer","text":"Zadvydas interprets a silent statute to imply a six-month limitation on other but related holding of aliens. So what would you think of reading this statute in order, in my opinion, not to violate a principle that goes back to if not -- not the Magna Carta, at least to Blackstone, that we read this statute the same way?"},{"src":"argument","who":"Ms. Wang","text":"So, if the Court wishes to draw a bright line, as you did in Zadvydas, I think that would be fine. But, really, we should follow the words Congress wrote."}]},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(2)","(a)(2)(1988)","(a)(2)(A)","(a)(2)(B)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"by":{"0":"31, 12, 31, 32, 32, 32","1":"passim","2":"13"},"q":[{"src":"brief","b":0,"text":"shall take into custody any alien convicted of an aggravated felony upon completion of the alien’s sentence for such conviction.","cite":"8 U.S.C. 1252(a)(2)"}]},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"33","1":"31, 36, 37"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"14, 33","1":"passim"}},{"t":"law","label":"Pub. L. No. 101-649","url":"https://www.govinfo.gov/link/statute/104/5049","by":{"0":"32","1":"31, 35"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","by":{"0":"2, 22","2":"20"}},{"t":"usc","label":"8 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/8/1103","subs":["(a)(1)","(g)","(a)"],"stext":{"head":"§1103. Powers and duties of the Secretary, the Under Secretary, and the Attorney General","paras":[[0,"(a) Secretary of Homeland Security"],[0,"(1) The Secretary of Homeland Security shall be charged with the administration and enforcement of this chapter and all other laws relating to the immigration and naturalization of aliens, except insofar as this chapter or such laws relate to the powers, functions, and duties conferred upon the President, Attorney General, the Secretary of State, the officers of the Department of State, or diplomatic or consular officers: Provided, however, That determination and ruling by the Attorney General with respect to all questions of law shall be controlling."],[0,"(2) He shall have control, direction, and supervision of all employees and of all the files and records of the Service."],[0,"(3) He shall establish such regulations; prescribe such forms of bond, reports, entries, and other papers; issue such instructions; and perform such other acts as he deems necessary for carrying out his authority under the provisions of this chapter."],[0,"(4) He may require or authorize any employee of the Service or the Department of Justice to perform or exercise any of the powers, privileges, or duties conferred or imposed by this chapter or regulations issued thereunder upon any other employee of the Service."],[0,"(5) He shall have the power and duty to control and guard the boundaries and borders of the United States against the illegal entry of aliens and shall, in his discretion, appoint for that purpose such number of employees of the Service as to him shall appear necessary and proper."],[0,"(6) He is authorized to confer or impose upon any employee of the United States, with the consent of the head of the Department or other independent establishment under whose jurisdiction the employee is serving, any of the powers, privileges, or duties conferred or imposed by this chapter or regulations issued thereunder upon officers or employees of the Service."],[0,"(7) He may, with the concurrence of the Secretary of State, establish offices of the Service in foreign countries; and, after consultation with the Secretary of State, he may, whenever in his judgment such action may be necessary to accomplish the purposes of this chapter, detail employees of the Service for duty in foreign countries."],[0,"(8) After consultation with the Secretary of State, the Attorney General may authorize officers of a foreign country to be stationed at preclearance facilities in the United States for the purpose of ensuring that persons traveling from or through the United States to that foreign country comply with that country's immigration and related laws."],[0,"(9) Those officers may exercise such authority and perform such duties as United States immigration officers are authorized to exercise and perform in that foreign country under reciprocal agreement, and they shall enjoy such reasonable privileges and immunities necessary for the performance of their duties as the government of their country extends to United States immigration officers."],[0,"(10) In the event the Attorney General determines that an actual or imminent mass influx of aliens arriving off the coast of the United States, or near a land border, presents urgent circumstances requiring an immediate Federal response, the Attorney General may authorize any State or local law enforcement officer, with the consent of the head of the department, agency, or establishment under whose jurisdiction the individual is serving, to perform or exercise any of the powers, privileges, or duties conferred or imposed by this chapter or regulations issued thereunder upon officers or employees of the Service."],[0,"(11) The Attorney General, in support of persons in administrative detention in non-Federal institutions, is authorized—"],[1,"(A) to make payments from funds appropriated for the administration and enforcement of the laws relating to immigration, naturalization, and alien registration for necessary clothing, medical care, necessary guard hire, and the housing, care, and security of persons detained by the Service pursuant to Federal law under an agreement with a State or political subdivision of a State; and"],[1,"(B) to enter into a cooperative agreement with any State, territory, or political subdivision thereof, for the necessary construction, physical renovation, acquisition of equipment, supplies or materials required to establish acceptable conditions of confinement and detention services in any State or unit of local government which agrees to provide guaranteed bed space for persons detained by the Service."],[0,"(b) Land acquisition authority"],[0,"(1) The Attorney General may contract for or buy any interest in land, including temporary use rights, adjacent to or in the vicinity of an international land border when the Attorney General deems the land essential to control and guard the boundaries and borders of the United States against any violation of this chapter."],[0,"(2) The Attorney General may contract for or buy any interest in land identified pursuant to paragraph (1) as soon as the lawful owner of that interest fixes a price for it and the Attorney General considers that price to be reasonable."],[0,"(3) When the Attorney General and the lawful owner of an interest identified pursuant to paragraph (1) are unable to agree upon a reasonable price, the Attorney General may commence condemnation proceedings pursuant to section 3113 of title 40."],[0,"(4) The Attorney General may accept for the United States a gift of any interest in land identified pursuant to paragraph (1)."],[0,"(c) Commissioner; appointment"],[0,"The Commissioner shall be a citizen of the United States and shall be appointed by the President, by and with the advice and consent of the Senate. He shall be charged with any and all responsibilities and authority in the administration of the Service and of this chapter which are conferred upon the Attorney General as may be delegated to him by the Attorney General or which may be prescribed by the Attorney General. The Commissioner may enter into cooperative agreements with State and local law enforcement agencies for the purpose of assisting in the enforcement of the immigration laws."],[0,"(d) Statistical information system"],[0,"(1) The Commissioner, in consultation with interested academicians, government agencies, and other parties, shall provide for a system for collection and dissemination, to Congress and the public, of information (not in individually identifiable form) useful in evaluating the social, economic, environmental, and demographic impact of immigration laws."],[0,"(2) Such information shall include information on the alien population in the United States, on the rates of naturalization and emigration of resident aliens, on aliens who have been admitted, paroled, or granted asylum, on nonimmigrants in the United States (by occupation, basis for admission, and duration of stay), on aliens who have not been admitted or have been removed from the United States, on the number of applications filed and granted for cancellation of removal, and on the number of aliens estimated to be present unlawfully in the United States in each fiscal year."],[0,"(3) Such system shall provide for the collection and dissemination of such information not less often than annually."],[0,"(e) Annual report"],[0,"(1) The Commissioner shall submit to Congress annually a report which contains a summary of the information collected under subsection (d) and an analysis of trends in immigration and naturalization."],[0,"(2) Each annual report shall include information on the number, and rate of denial administratively, of applications for naturalization, for each district office of the Service and by national origin group."],[0,"(f) Minimum number of agents in States"],[0,"The Attorney General shall allocate to each State not fewer than 10 full-time active duty agents of the Immigration and Naturalization Service to carry out the functions of the Service, in order to ensure the effective enforcement of this chapter."],[0,"(g) Attorney General"],[0,"(1) In general"],[1,"The Attorney General shall have such authorities and functions under this chapter and all other laws relating to the immigration and naturalization of aliens as were exercised by the Executive Office for Immigration Review, or by the Attorney General with respect to the Executive Office for Immigration Review, on the day before the effective date of the Immigration Reform, Accountability and Security Enhancement Act of 2002."],[0,"(2) Powers"],[1,"The Attorney General shall establish such regulations, prescribe such forms of bond, reports, entries, and other papers, issue such instructions, review such administrative determinations in immigration proceedings, delegate such authority, and perform such other acts as the Attorney General determines to be necessary for carrying out this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1103?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 39, 2, 39","1":"4, 4","2":"20"},"q":[{"src":"brief","b":2,"text":"determination and ruling by the Attorney General with respect to all questions of law shall be controlling.","cite":"8 U.S.C. 1103(a)(1)"}]},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)"],"by":{"0":"24","1":"4, 24"}},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","subs":["(b)"],"by":{"0":"24"}},{"t":"usc","label":"8 U.S.C. § 1226","url":"https://www.law.cornell.edu/uscode/text/8/1226","subs":["(a)","(c)","(c)(1)","(c)(1)(A)","(c)(2)"],"stext":{"head":"§1226. Apprehension and detention of aliens","paras":[[0,"(a) Arrest, detention, and release"],[0,"On a warrant issued by the Attorney General, an alien may be arrested and detained pending a decision on whether the alien is to be removed from the United States. Except as provided in subsection (c) and pending such decision, the Attorney General—"],[1,"(1) may continue to detain the arrested alien; and"],[1,"(2) may release the alien on—"],[2,"(A) bond of at least $1,500 with security approved by, and containing conditions prescribed by, the Attorney General; or"],[2,"(B) conditional parole; but"],[1,"(3) may not provide the alien with work authorization (including an \"employment authorized\" endorsement or other appropriate work permit), unless the alien is lawfully admitted for permanent residence or otherwise would (without regard to removal proceedings) be provided such authorization."],[0,"(b) Revocation of bond or parole"],[0,"The Attorney General at any time may revoke a bond or parole authorized under subsection (a), rearrest the alien under the original warrant, and detain the alien."],[0,"(c) Detention of criminal aliens"],[0,"(1) Custody"],[1,"The Attorney General shall take into custody any alien who—"],[2,"(A) is inadmissible by reason of having committed any offense covered in section 1182(a)(2) of this title,"],[2,"(B) is deportable by reason of having committed any offense covered in section 1227(a)(2)(A)(ii), (A)(iii), (B), (C), or (D) of this title,"],[2,"(C) is deportable under section 1227(a)(2)(A)(i) of this title on the basis of an offense for which the alien has been sentence 1 to a term of imprisonment of at least 1 year, or"],[2,"(D) is inadmissible under section 1182(a)(3)(B) of this title or deportable under section 1227(a)(4)(B) of this title,"],[1,"when the alien is released, without regard to whether the alien is released on parole, supervised release, or probation, and without regard to whether the alien may be arrested or imprisoned again for the same offense."],[0,"(2) Release"],[1,"The Attorney General may release an alien described in paragraph (1) only if the Attorney General decides pursuant to section 3521 of title 18 that release of the alien from custody is necessary to provide protection to a witness, a potential witness, a person cooperating with an investigation into major criminal activity, or an immediate family member or close associate of a witness, potential witness, or person cooperating with such an investigation, and the alien satisfies the Attorney General that the alien will not pose a danger to the safety of other persons or of property and is likely to appear for any scheduled proceeding. A decision relating to such release shall take place in accordance with a procedure that considers the severity of the offense committed by the alien."],[0,"(d) Identification of criminal aliens"],[0,"(1) The Attorney General shall devise and implement a system—"],[1,"(A) to make available, daily (on a 24-hour basis), to Federal, State, and local authorities the investigative resources of the Service to determine whether individuals arrested by such authorities for aggravated felonies are aliens;"],[1,"(B) to designate and train officers and employees of the Service to serve as a liaison to Federal, State, and local law enforcement and correctional agencies and courts with respect to the arrest, conviction, and release of any alien charged with an aggravated felony; and"],[1,"(C) which uses computer resources to maintain a current record of aliens who have been convicted of an aggravated felony, and indicates those who have been removed."],[0,"(2) The record under paragraph (1)(C) shall be made available—"],[1,"(A) to inspectors at ports of entry and to border patrol agents at sector headquarters for purposes of immediate identification of any alien who was previously ordered removed and is seeking to reenter the United States, and"],[1,"(B) to officials of the Department of State for use in its automated visa lookout system."],[0,"(3) Upon the request of the governor or chief executive officer of any State, the Service shall provide assistance to State courts in the identification of aliens unlawfully present in the United States pending criminal prosecution."],[0,"(e) Judicial review"],[0,"The Attorney General's discretionary judgment regarding the application of this section shall not be subject to review. No court may set aside any action or decision by the Attorney General under this section regarding the detention or release of any alien or the grant, revocation, or denial of bond or parole."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1226?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 29, 36, 37, passim, passim, 9, 14, passim","1":"passim, passim","2":"8, 10, passim, passim, 2, passim"},"q":[{"src":"brief","b":0,"text":"pending a decision on whether the alien is to be removed from the United States.","cite":"8 U.S.C. 1226(a)"},{"src":"brief","b":0,"text":"an alien described in paragraph (1).","cite":"8 U.S.C. 1226(c)"},{"src":"brief","b":1,"text":"[e]xcept as provided in subsection (c).","cite":"8 U.S.C. § 1226(a)"},{"src":"brief","b":1,"text":"without regard to whether the alien is released on parole, supervised release, or probation, and without regard to whether the alien may be arrested or imprisoned again for the same offense.","cite":"8 U.S.C. § 1226(c)(1)"},{"src":"brief","b":2,"text":"The [Secretary] shall take into custody any alien who * * * .","cite":"8 U.S.C. 1226(c)(1)"},{"src":"brief","b":2,"text":"[e]xcept as provided in subsection (c).","cite":"8 U.S.C. 1226(a)"},{"src":"opinion","who":"Justice Thomas, concurring in part and concurring in the judgment","text":"[e]xcept as provided in subsection (c).","cite":"8 U. S. C. §1226(a)"}]},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","subs":["(a)(2)(A)(iii)"],"stext":{"head":"§1227. Deportable aliens","paras":[[0,"(a) Classes of deportable aliens"],[0,"Any alien (including an alien crewman) in and admitted to the United States shall, upon the order of the Attorney General, be removed if the alien is within one or more of the following classes of deportable aliens:"],[0,"(1) Inadmissible at time of entry or of adjustment of status or violates status"],[0,"(A) Inadmissible aliens"],[2,"Any alien who at the time of entry or adjustment of status was within one or more of the classes of aliens inadmissible by the law existing at such time is deportable."],[0,"(B) Present in violation of law"],[2,"Any alien who is present in the United States in violation of this chapter or any other law of the United States, or whose nonimmigrant visa (or other documentation authorizing admission into the United States as a nonimmigrant) has been revoked under section 1201(i) of this title, is deportable."],[0,"(C) Violated nonimmigrant status or condition of entry"],[0,"(i) Nonimmigrant status violators"],[3,"Any alien who was admitted as a nonimmigrant and who has failed to maintain the nonimmigrant status in which the alien was admitted or to which it was changed under section 1258 of this title, or to comply with the conditions of any such status, is deportable."],[0,"(ii) Violators of conditions of entry"],[3,"Any alien whom the Secretary of Health and Human Services certifies has failed to comply with terms, conditions, and controls that were imposed under section 1182(g) of this title is deportable."],[0,"(D) Termination of conditional permanent residence"],[0,"(i) In general"],[3,"Any alien with permanent resident status on a conditional basis under section 1186a of this title (relating to conditional permanent resident status for certain alien spouses and sons and daughters) or under section 1186b of this title (relating to conditional permanent resident status for certain alien entrepreneurs, spouses, and children) who has had such status terminated under such respective section is deportable."],[0,"(ii) Exception"],[3,"Clause (i) shall not apply in the cases described in section 1186a(c)(4) of this title (relating to certain hardship waivers)."],[0,"(E) Smuggling"],[0,"(i) In general"],[3,"Any alien who (prior to the date of entry, at the time of any entry, or within 5 years of the date of any entry) knowingly has encouraged, induced, assisted, abetted, or aided any other alien to enter or to try to enter the United States in violation of law is deportable."],[0,"(ii) Special rule in the case of family reunification"],[3,"Clause (i) shall not apply in the case of alien who is an eligible immigrant (as defined in section 301(b)(1) of the Immigration Act of 1990), was physically present in the United States on May 5, 1988, and is seeking admission as an immediate relative or under section 1153(a)(2) of this title (including under section 112 of the Immigration Act of 1990) or benefits under section 301(a) of the Immigration Act of 1990 if the alien, before May 5, 1988, has encouraged, induced, assisted, abetted, or aided only the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(iii) Waiver authorized"],[3,"The Attorney General may, in his discretion for humanitarian purposes, to assure family unity, or when it is otherwise in the public interest, waive application of clause (i) in the case of any alien lawfully admitted for permanent residence if the alien has encouraged, induced, assisted, abetted, or aided only an individual who at the time of the offense was the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(F) Repealed. Pub. L. 104–208, div. C, title VI, §671(d)(1)(C), Sept. 30, 1996, 110 Stat. 3009–723"],[0,"(G) Marriage fraud"],[2,"An alien shall be considered to be deportable as having procured a visa or other documentation by fraud (within the meaning of section 1182(a)(6)(C)(i) of this title) and to be in the United States in violation of this chapter (within the meaning of subparagraph (B)) if—"],[3,"(i) the alien obtains any admission into the United States with an immigrant visa or other documentation procured on the basis of a marriage entered into less than 2 years prior to such admission of the alien and which, within 2 years subsequent to any admission of the alien in the United States, shall be judicially annulled or terminated, unless the alien establishes to the satisfaction of the Attorney General that such marriage was not contracted for the purpose of evading any provisions of the immigration laws, or"],[3,"(ii) it appears to the satisfaction of the Attorney General that the alien has failed or refused to fulfill the alien's marital agreement which in the opinion of the Attorney General was made for the purpose of procuring the alien's admission as an immigrant."],[0,"(H) Waiver authorized for certain misrepresentations"],[2,"The provisions of this paragraph relating to the removal of aliens within the United States on the ground that they were inadmissible at the time of admission as aliens described in section 1182(a)(6)(C)(i) of this title, whether willful or innocent, may, in the discretion of the Attorney General, be waived for any alien (other than an alien described in paragraph (4)(D)) who—"],[3,"(i)(I) is the spouse, parent, son, or daughter of a citizen of the United States or of an alien lawfully admitted to the United States for permanent residence; and"],[3,"(II) was in possession of an immigrant visa or equivalent document and was otherwise admissible to the United States at the time of such admission except for those grounds of inadmissibility specified under paragraphs (5)(A) and (7)(A) of section 1182(a) of this title which were a direct result of that fraud or misrepresentation."],[3,"(ii) is a VAWA self-petitioner."],[2,"A waiver of removal for fraud or misrepresentation granted under this subparagraph shall also operate to waive removal based on the grounds of inadmissibility directly resulting from such fraud or misrepresentation."],[0,"(2) Criminal offenses"],[0,"(A) General crimes"],[0,"(i) Crimes of moral turpitude"],[3,"Any alien who—"],[4,"(I) is convicted of a crime involving moral turpitude committed within five years (or 10 years in the case of an alien provided lawful permanent resident status under section 1255(j) of this title) after the date of admission, and"],[4,"(II) is convicted of a crime for which a sentence of one year or longer may be imposed,"],[0,"is deportable."],[0,"(ii) Multiple criminal convictions"],[3,"Any alien who at any time after admission is convicted of two or more crimes involving moral turpitude, not arising out of a single scheme of criminal misconduct, regardless of whether confined therefor and regardless of whether the convictions were in a single trial, is deportable."],[0,"(iii) Aggravated felony"],[3,"Any alien who is convicted of an aggravated felony at any time after admission is deportable."],[0,"(iv) High speed flight"],[3,"Any alien who is convicted of a violation of section 758 of title 18 (relating to high speed flight from an immigration checkpoint) is deportable."],[0,"(v) Failure to register as a sex offender"],[3,"Any alien who is convicted under section 2250 of title 18 is deportable."],[0,"(vi) Waiver authorized"],[3,"Clauses (i), (ii), (iii), and (iv) shall not apply in the case of an alien with respect to a criminal conviction if the alien subsequent to the criminal conviction has been granted a full and unconditional pardon by the President of the United States or by the Governor of any of the several States."],[0,"(B) Controlled substances"],[0,"(i) Conviction"],[3,"Any alien who at any time after admission has been convicted of a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21), other than a single offense involving possession for one's own use of 30 grams or less of marijuana, is deportable."],[0,"(ii) Drug abusers and addicts"],[3,"Any alien who is, or at any time after admission has been, a drug abuser or addict is deportable."],[0,"(C) Certain firearm offenses"],[2,"Any alien who at any time after admission is convicted under any law of purchasing, selling, offering for sale, exchanging, using, owning, possessing, or carrying, or of attempting or conspiring to purchase, sell, offer for sale, exchange, use, own, possess, or carry, any weapon, part, or accessory which is a firearm or destructive device (as defined in section 921(a) of title 18) in violation of any law is deportable."],[0,"(D) Miscellaneous crimes"],[2,"Any alien who at any time has been convicted (the judgment on such conviction becoming final) of, or has been so convicted of a conspiracy or attempt to violate—"],[3,"(i) any offense under chapter 37 (relating to espionage), chapter 105 (relating to sabotage), or chapter 115 (relating to treason and sedition) of title 18 for which a term of imprisonment of five or more years may be imposed;"],[3,"(ii) any offense under section 871 or 960 of title 18;"],[3,"(iii) a violation of any provision of the Military Selective Service Act (50 U.S.C. App. 451 et seq.) [now 50 U.S.C. 3801 et seq.] or the Trading With the Enemy Act (50 U.S.C. App. 1 et seq.) [now 50 U.S.C. 4301 et seq.]; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1227?type=usc&year=mostrecent&link-type=html"},"by":{"0":"24, 3"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"within one or more . . . classes of deportable aliens.","cite":"8 U. S. C. §1227(a)"}]},{"t":"usc","label":"8 U.S.C. § 1228","url":"https://www.law.cornell.edu/uscode/text/8/1228","subs":["(a)(3)(B)"],"by":{"0":"24, 18","1":"48"}},{"t":"usc","label":"8 U.S.C. § 1229","url":"https://www.law.cornell.edu/uscode/text/8/1229","by":{"0":"24"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(e)(2)"],"by":{"0":"2, 24, 3"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(a)(4)(A)","(a)"],"stext":{"head":"§1231. Detention and removal of aliens ordered removed","paras":[[0,"(a) Detention, release, and removal of aliens ordered removed"],[0,"(1) Removal period"],[0,"(A) In general"],[2,"Except as otherwise provided in this section, when an alien is ordered removed, the Attorney General shall remove the alien from the United States within a period of 90 days (in this section referred to as the \"removal period\")."],[0,"(B) Beginning of period"],[2,"The removal period begins on the latest of the following:"],[3,"(i) The date the order of removal becomes administratively final."],[3,"(ii) If the removal order is judicially reviewed and if a court orders a stay of the removal of the alien, the date of the court's final order."],[3,"(iii) If the alien is detained or confined (except under an immigration process), the date the alien is released from detention or confinement."],[0,"(C) Suspension of period"],[2,"The removal period shall be extended beyond a period of 90 days and the alien may remain in detention during such extended period if the alien fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure or conspires or acts to prevent the alien's removal subject to an order of removal."],[0,"(2) Detention"],[1,"During the removal period, the Attorney General shall detain the alien. Under no circumstance during the removal period shall the Attorney General release an alien who has been found inadmissible under section 1182(a)(2) or 1182(a)(3)(B) of this title or deportable under section 1227(a)(2) or 1227(a)(4)(B) of this title."],[0,"(3) Supervision after 90-day period"],[1,"If the alien does not leave or is not removed within the removal period, the alien, pending removal, shall be subject to supervision under regulations prescribed by the Attorney General. The regulations shall include provisions requiring the alien—"],[2,"(A) to appear before an immigration officer periodically for identification;"],[2,"(B) to submit, if necessary, to a medical and psychiatric examination at the expense of the United States Government;"],[2,"(C) to give information under oath about the alien's nationality, circumstances, habits, associations, and activities, and other information the Attorney General considers appropriate; and"],[2,"(D) to obey reasonable written restrictions on the alien's conduct or activities that the Attorney General prescribes for the alien."],[0,"(4) Aliens imprisoned, arrested, or on parole, supervised release, or probation"],[0,"(A) In general"],[2,"Except as provided in section 259(a) 1 of title 42 and paragraph (2),2 the Attorney General may not remove an alien who is sentenced to imprisonment until the alien is released from imprisonment. Parole, supervised release, probation, or possibility of arrest or further imprisonment is not a reason to defer removal."],[0,"(B) Exception for removal of nonviolent offenders prior to completion of sentence of imprisonment"],[2,"The Attorney General is authorized to remove an alien in accordance with applicable procedures under this chapter before the alien has completed a sentence of imprisonment—"],[3,"(i) in the case of an alien in the custody of the Attorney General, if the Attorney General determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense related to smuggling or harboring of aliens or an offense described in section 1101(a)(43)(B), (C), (E), (I), or (L) of this title 3 and (II) the removal of the alien is appropriate and in the best interest of the United States; or"],[3,"(ii) in the case of an alien in the custody of a State (or a political subdivision of a State), if the chief State official exercising authority with respect to the incarceration of the alien determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense described in section 1101(a)(43)(C) or (E) of this title), (II) the removal is appropriate and in the best interest of the State, and (III) submits a written request to the Attorney General that such alien be so removed."],[0,"(C) Notice"],[2,"Any alien removed pursuant to this paragraph shall be notified of the penalties under the laws of the United States relating to the reentry of deported aliens, particularly the expanded penalties for aliens removed under subparagraph (B)."],[0,"(D) No private right"],[2,"No cause or claim may be asserted under this paragraph against any official of the United States or of any State to compel the release, removal, or consideration for release or removal of any alien."],[0,"(5) Reinstatement of removal orders against aliens illegally reentering"],[1,"If the Attorney General finds that an alien has reentered the United States illegally after having been removed or having departed voluntarily, under an order of removal, the prior order of removal is reinstated from its original date and is not subject to being reopened or reviewed, the alien is not eligible and may not apply for any relief under this chapter, and the alien shall be removed under the prior order at any time after the reentry."],[0,"(6) Inadmissible or criminal aliens"],[1,"An alien ordered removed who is inadmissible under section 1182 of this title, removable under section 1227(a)(1)(C), 1227(a)(2), or 1227(a)(4) of this title or who has been determined by the Attorney General to be a risk to the community or unlikely to comply with the order of removal, may be detained beyond the removal period and, if released, shall be subject to the terms of supervision in paragraph (3)."],[0,"(7) Employment authorization"],[1,"No alien ordered removed shall be eligible to receive authorization to be employed in the United States unless the Attorney General makes a specific finding that—"],[2,"(A) the alien cannot be removed due to the refusal of all countries designated by the alien or under this section to receive the alien, or"],[2,"(B) the removal of the alien is otherwise impracticable or contrary to the public interest."],[0,"(b) Countries to which aliens may be removed"],[0,"(1) Aliens arriving at the United States"],[1,"Subject to paragraph (3)—"],[0,"(A) In general"],[2,"Except as provided by subparagraphs (B) and (C), an alien who arrives at the United States and with respect to whom proceedings under section 1229a of this title were initiated at the time of such alien's arrival shall be removed to the country in which the alien boarded the vessel or aircraft on which the alien arrived in the United States."],[0,"(B) Travel from contiguous territory"],[2,"If the alien boarded the vessel or aircraft on which the alien arrived in the United States in a foreign territory contiguous to the United States, an island adjacent to the United States, or an island adjacent to a foreign territory contiguous to the United States, and the alien is not a native, citizen, subject, or national of, or does not reside in, the territory or island, removal shall be to the country in which the alien boarded the vessel that transported the alien to the territory or island."],[0,"(C) Alternative countries"],[2,"If the government of the country designated in subparagraph (A) or (B) is unwilling to accept the alien into that country's territory, removal shall be to any of the following countries, as directed by the Attorney General:"],[3,"(i) The country of which the alien is a citizen, subject, or national."],[3,"(ii) The country in which the alien was born."],[3,"(iii) The country in which the alien has a residence."],[3,"(iv) A country with a government that will accept the alien into the country's territory if removal to each country described in a previous clause of this subparagraph is impracticable, inadvisable, or impossible."],[0,"(2) Other aliens"],[1,"Subject to paragraph (3)—"],[0,"(A) Selection of country by alien"],[2,"Except as otherwise provided in this paragraph—"],[3,"(i) any alien not described in paragraph (1) who has been ordered removed may designate one country to which the alien wants to be removed, and"],[3,"(ii) the Attorney General shall remove the alien to the country the alien so designates."],[0,"(B) Limitation on designation"],[2,"An alien may designate under subparagraph (A)(i) a foreign territory contiguous to the United States, an adjacent island, or an island adjacent to a foreign territory contiguous to the United States as the place to which the alien is to be removed only if the alien is a native, citizen, subject, or national of, or has resided in, that designated territory or island."],[0,"(C) Disregarding designation"],[2,"The Attorney General may disregard a designation under subparagraph (A)(i) if—"],[3,"(i) the alien fails to designate a country promptly;"],[3,"(ii) the government of the country does not inform the Attorney General finally, within 30 days after the date the Attorney General first inquires, whether the government will accept the alien into the country;"],[3,"(iii) the government of the country is not willing to accept the alien into the country; or"],[3,"(iv) the Attorney General decides that removing the alien to the country is prejudicial to the United States."],[0,"(D) Alternative country"],[2,"If an alien is not removed to a country designated under subparagraph (A)(i), the Attorney General shall remove the alien to a country of which the alien is a subject, national, or citizen unless the government of the country—"],[3,"(i) does not inform the Attorney General or the alien finally, within 30 days after the date the Attorney General first inquires or within another period of time the Attorney General decides is reasonable, whether the government will accept the alien into the country; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1231?type=usc&year=mostrecent&link-type=html"},"by":{"0":"31, 18","1":"19, 22","2":"8"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"until the alien is released from imprisonment.","cite":"8 U. S. C. §1231(a)(4)(A)"}]},{"t":"usc","label":"8 U.S.C. § 1256","url":"https://www.law.cornell.edu/uscode/text/8/1256","subs":["(a)"],"by":{"0":"25"}},{"t":"law","label":"Pub. L. No. 102-232","url":"https://www.govinfo.gov/link/statute/105/1751","by":{"0":"32"}},{"t":"usc","label":"6 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/6/202","subs":["(3)"],"stext":{"head":"§202. Border, maritime, and transportation responsibilities","paras":[[0,"The Secretary shall be responsible for the following:"],[1,"(1) Preventing the entry of terrorists and the instruments of terrorism into the United States."],[1,"(2) Securing the borders, territorial waters, ports, terminals, waterways, and air, land, and sea transportation systems of the United States, including managing and coordinating those functions transferred to the Department at ports of entry."],[1,"(3) Carrying out the immigration enforcement functions vested by statute in, or performed by, the Commissioner of Immigration and Naturalization (or any officer, employee, or component of the Immigration and Naturalization Service) immediately before the date on which the transfer of functions specified under section 251 of this title takes effect."],[1,"(4) Establishing and administering rules, in accordance with section 236 of this title, governing the granting of visas or other forms of permission, including parole, to enter the United States to individuals who are not a citizen or an alien lawfully admitted for permanent residence in the United States."],[1,"(5) Establishing national immigration enforcement policies and priorities."],[1,"(6) Except as provided in part C of this subchapter, administering the customs laws of the United States."],[1,"(7) Conducting the inspection and related administrative functions of the Department of Agriculture transferred to the Secretary of Homeland Security under section 231 of this title."],[1,"(8) In carrying out the foregoing responsibilities, ensuring the speedy, orderly, and efficient flow of lawful traffic and commerce."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/6/202?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2","1":"4"}},{"t":"usc","label":"6 U.S.C. § 251","url":"https://www.law.cornell.edu/uscode/text/6/251","by":{"0":"2","1":"4"}},{"t":"usc","label":"6 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/6/271","subs":["(b)"],"by":{"0":"2","1":"4"}},{"t":"usc","label":"6 U.S.C. § 542","url":"https://www.law.cornell.edu/uscode/text/6/542","by":{"0":"2","1":"4"}},{"t":"usc","label":"6 U.S.C. § 557","url":"https://www.law.cornell.edu/uscode/text/6/557","by":{"0":"2","1":"4"}},{"t":"usc","label":"8 U.S.C. § 1551","url":"https://www.law.cornell.edu/uscode/text/8/1551","by":{"0":"2"}},{"t":"usc","label":"18 U.S.C. § 3282","url":"https://www.law.cornell.edu/uscode/text/18/3282","subs":["(a)"],"by":{"0":"20"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(a)"],"by":{"0":"20"}},{"t":"reg","label":"55 Fed. Reg. 24,859","url":"https://www.govinfo.gov/link/fr/55/24859","by":{"0":"31, 32"}},{"t":"reg","label":"57 Fed. Reg. 11,568","url":"https://www.govinfo.gov/link/fr/57/11568","by":{"0":"33","1":"35"}},{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"by":{"1":"44"},"q":[{"src":"brief","b":1,"text":"[T]he writ of habeas corpus is . . . an indispensable mechanism for monitoring the separation of powers.","cite":"553 U.S. 723, 765"}]},{"t":"case","label":"Burrage v. United States","cite":"571 U.S. 204","y":2014,"id":"2013/12-7515","sc":1,"by":{"1":"28"}},{"t":"case","label":"Castañeda v. Souza","cite":"769 F.3d 32","y":2014,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/769/32/","by":{"1":"41"}},{"t":"case","label":"City of Edmonds v. Oxford House, Inc.","cite":"514 U.S. 725","y":1995,"id":"1994/94-23","sc":1,"by":{"1":"19"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"by":{"1":"42","2":"15"},"q":[{"src":"brief","b":1,"text":"It is not at all unusual to give a statute’s ambiguous language a limiting construction called for by one of the statute’s applications, even though other of the statute’s applications, standing alone, would not support the same limitation.","cite":"543 U.S. 371, 380"},{"src":"brief","b":2,"text":"comes into play only when, after the application of ordinary textual analysis, the statute is found to be susceptible of more than one construction,","cite":"543 U.S. 371, 385"}]},{"t":"case","label":"Comm’r of Internal Revenue v. Clark","cite":"489 U.S. 726","y":1989,"id":"1988/87-1168","sc":1,"by":{"1":"19"}},{"t":"case","label":"Conn. Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"by":{"1":"20"}},{"t":"case","label":"Crowell v. Benson","cite":"285 U.S. 22","y":1932,"id":"scdb/1931-083","sc":1,"by":{"1":"38"}},{"t":"case","label":"Deal v. United States","cite":"508 U.S. 129","y":1993,"id":"1992/91-8199","sc":1,"by":{"1":"26"}},{"t":"case","label":"Foucha v. Louisiana","cite":"504 U.S. 71","y":1992,"id":"1991/90-5844","sc":1,"by":{"1":"39"}},{"t":"case","label":"General Dynamics Land Systems v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"a phrase gathers meaning from the words around it.","cite":"540 U.S. 581, 596"}]},{"t":"case","label":"Gutierrez-Brizuela v. Lynch","cite":"834 F.3d 1142","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/834/1142/","by":{"1":"45"}},{"t":"case","label":"INS v. Cardozo-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"by":{"1":"19"}},{"t":"case","label":"Judulang v. Holder","cite":"565 U.S. 42","y":2011,"id":"2011/10-694","sc":1,"by":{"1":"43, 46"},"q":[{"src":"brief","b":1,"text":"unmoored from the purposes and concerns","cite":"565 U.S. at 64"}]},{"t":"case","label":"Kansas v. Hendricks","cite":"521 U.S. 346","y":1997,"id":"1996/95-1649","sc":1,"by":{"1":"39"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"‘constitutionally protected interest in avoiding physical restraint,’","cite":"521 U. S. 346, 356"}]},{"t":"case","label":"Khodr v. Adduci","cite":"697 F. Supp. 2d 774","y":2010,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/697/774/","by":{"1":"22"}},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"Where Congress includes particular language in one section of a statute but omits it in another section of the same Act, it is generally presumed that Congress acts intentionally and purposely in the disparate inclusion or exclusion.","cite":"556 U.S. 418, 430"}]},{"t":"case","label":"Pereira v. Sessions","cite":"138 S. Ct. 2105","y":2018,"id":"2017/17-459","sc":1,"by":{"1":"passim"},"q":[{"src":"brief","b":1,"text":"do not justify departing from the statute’s clear text.","cite":"138 S. Ct. at 2118"},{"src":"brief","b":1,"text":"practical considerations . . . do not justify departing from the statute’s clear text.","cite":"138 S. Ct. at 2118"},{"src":"argument","who":"Ms. Wang","text":"I'd note, finally, Justice Alito, that -- that the Court dealt with similar parallel arguments by the government in the Pereira and Moncrief cases, and the Court said, look, the government can point to these practical considerations, but at the end of the day, we're looking at the words that Congress wrote."}]},{"t":"case","label":"Saysana v. Gillen","cite":"590 F.3d 7","y":2009,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/590/7/","by":{"1":"passim"}},{"t":"case","label":"Schall v. Martin","cite":"467 U.S. 253","y":1984,"id":"1983/82-1248","sc":1,"by":{"1":"39"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"by":{"1":"25, 27"}},{"t":"case","label":"Solid Waste Agency of N. Cook Cnty. v. U.S. Army Corps of Engineers","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"by":{"1":"44"}},{"t":"case","label":"TRW Inc., v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"a statute ought . . . to be so construed that, if it can be prevented, no clause, sentence or word shall be superfluous, void, or insignificant.","cite":"534 U.S. 19, 31"}]},{"t":"case","label":"United States v. Calamaro","cite":"354 U.S. 351","y":1957,"id":"1956/304","sc":1,"by":{"1":"34, 35"}},{"t":"case","label":"United States v. Salerno","cite":"481 U.S. 739","y":1987,"id":"1986/86-87","sc":1,"by":{"1":"39"}},{"t":"case","label":"United States v. Willings","cite":"8 U.S. 48","y":1807,"id":"scdb/1807-005","sc":1,"by":{"1":"26"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"by":{"1":"36"}},{"t":"usc","label":"8 U.S.C. § 1226a","url":"https://www.law.cornell.edu/uscode/text/8/1226a","subs":["(a)"],"by":{"1":"8"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","subs":["(a)","(a)(3)","(b)","(b)(1)(C)"],"by":{"1":"42","2":"17, 17, 17, 17"}},{"t":"usc","label":"8 U.S.C. § 1357","url":"https://www.law.cornell.edu/uscode/text/8/1357","subs":["(g)"],"by":{"1":"48"}},{"t":"usc","label":"8 U.S.C. § 1537","url":"https://www.law.cornell.edu/uscode/text/8/1537","by":{"1":"8"}},{"t":"reg","label":"8 C.F.R. § 242.2","url":"https://www.ecfr.gov/current/title-8/section-242.2","subs":["(c)(1)"],"by":{"1":"34"}},{"t":"reg","label":"8 C.F.R. pt. 1003","url":"https://www.ecfr.gov/current/title-8/part-1003","subs":["(h)"],"by":{"1":"35"}},{"t":"reg","label":"8 C.F.R. § 1003.19","url":"https://www.ecfr.gov/current/title-8/section-1003.19","subs":["(a)"],"by":{"1":"3, 16"}},{"t":"reg","label":"8 C.F.R. § 1236.1","url":"https://www.ecfr.gov/current/title-8/section-1236.1","subs":["(c)(8)","(d)"],"by":{"1":"16, 3, 15"}},{"t":"reg","label":"55 Fed. Reg. 24,858","url":"https://www.govinfo.gov/link/fr/55/24858","by":{"1":"34","2":"13"}},{"t":"reg","label":"55 Fed. Reg. 43,326","url":"https://www.govinfo.gov/link/fr/55/43326","by":{"1":"34"}},{"t":"case","label":"INS v. Yueh-Shaio Yang","cite":"519 U.S. 26","y":1996,"id":"1996/95-938","sc":1,"by":{"2":"18"}}]};